// Step 1: is this request really from the shop, and is it fresh?
// Signature = HMAC-SHA256(shop secret, "<timestamp>.<raw body>"), sent as "v1=<hex>".
// Secrets live only in n8n Variables, never in this code.
const crypto = require('crypto');
const MAX_AGE_SECONDS = 300; // 5 minutes, both into the past and the future
const SECRET_VARIABLE = {
  shop_mossbank: 'IHM_SECRET_MOSSBANK',
  shop_quillmoor: 'IHM_SECRET_QUILLMOOR',
  shop_tallowick: 'IHM_SECRET_TALLOWICK'
};

const item = $input.first();
const headers = item.json.headers || {};
const shop = String(headers['x-ihm-shop'] || '');
const tsHeader = headers['x-ihm-timestamp'];
const sigHeader = String(headers['x-ihm-signature'] || '');
const testRun = String(headers['x-ihm-test-run'] || '');

let raw = null;
if (item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
}

const base = {
  received_at: new Date().toISOString(),
  shop_id: shop,
  event_id: '',
  test_run: testRun,
  source: testRun ? 'test' : 'live',
  raw_body: raw
};
const result = (ok, outcome, reason, status) => [{ json: { ...base, ok, outcome, reason, http_status: status } }];

const variableName = SECRET_VARIABLE[shop];
if (!variableName) return result(false, 'rejected_signature', 'unknown shop', 401);
const secret = $vars[variableName];
if (!secret) return result(false, 'rejected_config', 'signing secret not configured', 500);
if (raw === null) return result(false, 'rejected_validation', 'raw body not available', 400);

const match = /^v1=([0-9a-f]{64})$/.exec(sigHeader);
if (!match) return result(false, 'rejected_signature', sigHeader ? 'malformed signature header' : 'missing signature header', 401);

if (tsHeader === undefined || tsHeader === '') return result(false, 'rejected_timestamp', 'missing timestamp header', 401);
if (!/^[0-9]{9,11}$/.test(String(tsHeader))) return result(false, 'rejected_timestamp', 'timestamp is not unix seconds', 401);
const ts = Number(tsHeader);

const expected = crypto.createHmac('sha256', secret).update(tsHeader + '.' + raw, 'utf8').digest('hex');
const same = crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(match[1], 'hex'));
if (!same) return result(false, 'rejected_signature', 'signature does not match', 401);

const age = Math.floor(Date.now() / 1000) - ts;
if (age > MAX_AGE_SECONDS) return result(false, 'rejected_timestamp', 'timestamp too old (' + age + ' s)', 401);
if (age < -MAX_AGE_SECONDS) return result(false, 'rejected_timestamp', 'timestamp in the future (' + (-age) + ' s)', 401);

return result(true, 'signature_ok', '', 200);

// Step 2: required fields and types. Every problem is listed, not just the first one.
const input = $input.first().json;
const errors = [];
let body = null;
try { body = JSON.parse(input.raw_body); } catch (e) { errors.push('body is not valid JSON'); }

const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = v => typeof v === 'string' && v.trim() !== '';
const EVENT_TYPES = ['order.created', 'customer.updated'];

if (body !== null && !isObj(body)) errors.push('body must be a JSON object');
if (isObj(body)) {
  if (!('event_id' in body)) errors.push('missing event_id');
  else if (typeof body.event_id !== 'string' || !/^evt_[A-Za-z0-9]{8,40}$/.test(body.event_id)) errors.push('event_id must look like evt_ + 8-40 letters/digits');

  if (!('event_type' in body)) errors.push('missing event_type');
  else if (!EVENT_TYPES.includes(body.event_type)) errors.push('unknown event_type');

  if (!('occurred_at' in body)) errors.push('missing occurred_at');
  else if (typeof body.occurred_at !== 'string' || isNaN(Date.parse(body.occurred_at)) || !/^\d{4}-\d{2}-\d{2}T/.test(body.occurred_at)) errors.push('occurred_at must be an ISO 8601 date-time');

  if (!('shop_id' in body)) errors.push('missing shop_id');
  else if (body.shop_id !== input.shop_id) errors.push('shop_id in body does not match the signing shop');

  if (!('data' in body)) errors.push('missing data');
  else if (!isObj(body.data)) errors.push('data must be an object');
  else if (body.event_type === 'order.created') {
    const d = body.data;
    if (!isText(d.order_id)) errors.push('data.order_id must be text');
    if (typeof d.total !== 'number' || !isFinite(d.total)) errors.push('data.total must be a number');
    else if (d.total < 0) errors.push('data.total must be 0 or more');
    if (typeof d.currency !== 'string' || !/^[A-Z]{3}$/.test(d.currency)) errors.push('data.currency must be 3 capital letters');
  } else if (body.event_type === 'customer.updated') {
    const d = body.data;
    if (!isText(d.customer_id)) errors.push('data.customer_id must be text');
    if (typeof d.email_opt_in !== 'boolean') errors.push('data.email_opt_in must be true or false');
  }
}

const ok = errors.length === 0;
return [{ json: {
  ...input,
  ok,
  event_id: isObj(body) && typeof body.event_id === 'string' ? body.event_id.slice(0, 60) : '',
  event_type: ok ? body.event_type : '',
  occurred_at: ok ? body.occurred_at : '',
  outcome: ok ? 'valid' : 'rejected_validation',
  reason: errors.join('; '),
  http_status: ok ? 200 : 400
} }];

// Step 3: idempotency. The same shop + event_id is processed only once.
const v = $('Validate fields and types').first().json;
const seen = $input.all().some(i => i.json && i.json.id !== undefined);
return [{ json: {
  ...v,
  outcome: seen ? 'duplicate' : 'new',
  reason: seen ? 'event_id already processed, ignored' : '',
  http_status: 200
} }];

// Step 4: the event is stored, so it is now safe to answer 200.
const v = $('New or duplicate?').first().json;
return [{ json: { ...v, outcome: 'accepted', reason: '', http_status: 200 } }];
